INSERT INTO `essennewquestdesc` VALUES (100, '-');
INSERT INTO `essennewquestdesc` VALUES (101, '<color=ffffff>ファームに畑を設置して豆を収穫してみよう！</color><br><br><color=33ccfe>ファームに豆畑を設置して、成長水をかけよう。<br>豆を1個収穫したら、ファームピエロに持っていこう。</color><br><br><color=ffcc00>豆を1個収穫<br><ERASE_TAG_COMPLETE_STATE><CONDITION_GOAL_NUM=302> / 1</ERASE_TAG_COMPLETE_STATE></color>');
INSERT INTO `essennewquestdesc` VALUES (102, '<color=ffffff>ファームポイントはファーム作りに必要なファームのインテリア<br>アイテムを手に入れるための重要な手段だよ。</color><br><br><color=33ccfe>ファームピエロからもらった成長水をファームピエロの横にある<br>畑にかけた後、ファームピエロに報告しよう。</color><br><br><color=ffcc00>ファームピエロの畑に成長水をかける。</color>');
INSERT INTO `essennewquestdesc` VALUES (103, '<color=ffffff>錬金に欠かせないカードを大事にしないとダメだよ！</color><br><br><color=33ccfe>復元する童話の寺院にいる対戦チャンネル教官のところに行き<br>「トレーニング」マップを走ろう。ランダムで出てくるカード<br>［No.26 童話の国の危機］を2枚集めて錬金術師に持っていこう。</color><br><br><color=ffcc00>［No.26 童話の国の危機］カードを2枚収集<br><ERASE_TAG_COMPLETE_STATE><CONDITION_GOAL_NUM=327> / <CONDITION_NUM= 327></ERASE_TAG_COMPLETE_STATE></color>');
INSERT INTO `essennewquestdesc` VALUES (104, '<color=ffffff>運勢を占う人にはいろんな特典をあげちゃうよ～！</color><br><br><color=33ccfe>運勢を占ってもらったら、アキに報告しよう。</color><br><br><color=ffcc00>運勢占い1回</color>');
INSERT INTO `essennewquestdesc` VALUES (105, '<color=ffffff>ミッションチャンネルの教官様が<br>あなたの心強い味方になってくださることを信じます。</color><br><br><color=33ccfe>復元する童話の寺院にいるミッションチャンネルの教官に<br>会ってみよう。</color><br><br><color=ffcc00>ミッションチャンネルの教官に会う</color>');
INSERT INTO `essennewquestdesc` VALUES (106, '<color=ffffff>最初からうまくできる人はいないと思うよ。</color><br><br><color=33ccfe>ミッションチャンネル教官のところに行き<br>チュートリアルミッションをすべてクリアしよう。</color><br><br><color=ffcc00>ミッションチャンネルで チュートリアルをすべてクリアする</color>');
INSERT INTO `essennewquestdesc` VALUES (107, '<color=ffffff>学習で強くなることと実践で強くなることは<br>比べ物にならないほどの差があります。</color><br><br><color=33ccfe>復元する童話の寺院にいる対戦チャンネル教官のところに行き<br>［ハードルイージー］マップを走ろう。</color><br><br><color=ffcc00>［ハードルイージー］マップを２回完走</color>');
INSERT INTO `essennewquestdesc` VALUES (108, '<color=ffffff>錬金術のアイテムはあなたを何段階も強力にしてくれます。</color><br><br><color=33ccfe>錬金術おばさんから教わった内容をもとに錬金アイテムを<br>製作してみよう。</color><br><br><color=ffcc00>てんとう虫服装を作って報告</color>');
INSERT INTO `essennewquestdesc` VALUES (109, '<color=ffffff>イドゥン様はシムに接近するために前哨基地を建設<br>していらっしゃるけど、人手が全然足りてないみたい。</color><br><br><color=33ccfe>イドゥンの前哨基地に行き、イドゥンと話してみよう。</color><br><br><color=ffcc00>イドゥンと会話</color>');
INSERT INTO `essennewquestdesc` VALUES (110, '<color=ffffff>現在、微かにシムの位置を把握していますが<br>道を作るのに大変苦労してます。</color><br><br><color=33ccfe>対戦チャンネル教官のところに行き<br>［サバイバル］マップを走ろう。</color><br><br><color=ffcc00>［No.35 苦悩するアンリ］カードを3枚収集<br><ERASE_TAG_COMPLETE_STATE><CONDITION_GOAL_NUM=238> / <CONDITION_NUM= 238></ERASE_TAG_COMPLETE_STATE></color>');
INSERT INTO `essennewquestdesc` VALUES (111, '<color=ffffff>この鍵はどんな錠でも開けられる強力な力を持っている。<br>これをイドゥン様に渡してくれ。</color><br><br><color=33ccfe>イドゥンの前哨基地に行き、イドゥンと話してみよう。</color><br><br><color=ffcc00>イドゥンに万能黄金の鍵を渡す</color><br><color=00ff00>(マイルーム→その他→ゲームカテゴリーから確認可能)</color>');
INSERT INTO `essennewquestdesc` VALUES (112, '<color=ffffff>今の私たちの力では立ち向えないほどの闇です。<br>もう一度その道を塞がなければいけません。 </color><br><br><color=33ccfe>公園にいる錬金術師のおじさんと話してみよう。</color><br><br><color=ffcc00>錬金術師のおじさんにイドゥンから聞いた状況を伝える</color>');
INSERT INTO `essennewquestdesc` VALUES (113, '<color=ffffff>現在いくつか材料が足りないんだ。<br>急いで持ってきてくれないか？</color><br><br><color=33ccfe>対戦チャンネル教官のところに行き<br>［サバイバル］マップを走ろう。</color><br><br><color=ffcc00>［No.36 地下室の大掃除］カードを2枚収集<br><ERASE_TAG_COMPLETE_STATE><CONDITION_GOAL_NUM=243> / <CONDITION_NUM= 243></ERASE_TAG_COMPLETE_STATE></color>');
INSERT INTO `essennewquestdesc` VALUES (114, '<color=ffffff>今まで起きたすべての事に関して書いた手紙です。<br>この手紙をミッションチャンネルの教官に渡してください。</color><br><br><color=33ccfe>復元する童話の寺院にいるミッションチャンネルの教官と<br>話してみよう。</color><br><br><color=ffcc00>ミッションチャンネルの教官にイドゥンからの手紙を渡す</color><br><color=00ff00>(マイルーム→その他→ゲームカテゴリーから確認可能)</color>');
INSERT INTO `essennewquestdesc` VALUES (115, '<color=ffffff>いろんな友達がたくさんいればいるほど<br>テイルズランドでの生活も楽しくなるよ！</color><br><br><color=33ccfe>友達登録で、メッセンジャーに友達を3人以上登録しよう。</color><br><br><color=ffcc00>友達を3人集める</color><br><color=00ff00>(友達はメッセンジャーから確認可能)</color>');
INSERT INTO `essennewquestdesc` VALUES (116, '<color=ffffff>童話のマップを一度走るだけでも願いのエネルギーを<br>集める助けになるから！<br><br><color=33ccfe>復元する童話の寺院へ移動し、対戦チャンネル教官に会ってから<br>［雪女］マップを走ってみよう。</color><br><br><color=ffcc00>［雪女］マップを1回完走<br><ERASE_TAG_COMPLETE_STATE><CONDITION_GOAL_NUM=687> / <CONDITION_NUM= 687></ERASE_TAG_COMPLETE_STATE></color>');
INSERT INTO `essennewquestdesc` VALUES (117, 'NULL');
INSERT INTO `essennewquestdesc` VALUES (118, '<color=ffffff>うわっ、今豆乳が飲めないと大変なことが起こりそう！<br>豆乳だけはちゃんと決められた時間に飲まないと！</color><br><br><color=33ccfe>ファームピエロに会って豆乳をもらってこよう。</color><br><br><color=ffcc00>豆乳1本獲得<br><ERASE_TAG_COMPLETE_STATE><CONDITION_GOAL_NUM=738> /  1</ERASE_TAG_COMPLETE_STATE></color>');
INSERT INTO `essennewquestdesc` VALUES (119, '<color=ffffff>ごめん、技術者ピエロたちが豆乳を全部持ってっちゃったんだ。<br>豆乳はすぐ作ってやるから、豆を頼んでもいいかな？</color><br><br><color=33ccfe>ファームに豆畑を設置して豆を5個収穫したら<br>ファームピエロに持って行こう。</color><br><br><color=ffcc00>豆を5個収穫<br><ERASE_TAG_COMPLETE_STATE><CONDITION_GOAL_NUM=691> / <CONDITION_NUM= 691></ERASE_TAG_COMPLETE_STATE></color>');
INSERT INTO `essennewquestdesc` VALUES (120, '<color=ffffff>青の門番のやつについて知りたがる理由が分からんな。<br>対戦チャンネルの教官様なら君の質問に答えられるかもな…。</color><br><br><color=33ccfe>復元する童話の寺院に移動して対戦チャンネルの教官に会おう。</color><br><br><color=ffcc00>対戦チャンネル教官と会話する</color>');
INSERT INTO `essennewquestdesc` VALUES (121, '<color=ffffff>シムについては僕もあんまり知らないよ。<br>ファームピエロ君なら詳しい事情を知ってるんじゃないかな？</color><br><br><color=33ccfe>公園にいるファームピエロに会い、シムについて聞いてみよう。</color><br><br><color=ffcc00>ファームピエロと会話する</color>');
INSERT INTO `essennewquestdesc` VALUES (122, '<color=ffffff>ライセンスは誰でも簡単にもらえるものではありません。<br>箱の中の任務を全てクリアし、あなたの能力を証明してください。</color><br><br><color=33ccfe>イドゥンの羊皮紙ボックスの中の任務をすべてクリアしよう。</color><br><br><color=ffcc00>任務10個をクリアする<br><ERASE_TAG_COMPLETE_STATE><CONDITION_GOAL_NUM=741> / <CONDITION_NUM= 741></ERASE_TAG_COMPLETE_STATE></color>');
INSERT INTO `essennewquestdesc` VALUES (123, '<color=ffffff>話が長引いちゃって、シムたちにあげるエサの準備ができてないんだ。<br>君にも責任あるんだから助けてくれないか？</color><br><br><color=33ccfe>走る前にマップで報奨としてでる「ホコリ」を10個集めよう。</color><br><br><color=ffcc00>ホコリ10個収集<br><ERASE_TAG_COMPLETE_STATE><CONDITION_GOAL_NUM=744> / <CONDITION_NUM= 744></ERASE_TAG_COMPLETE_STATE></color>');
INSERT INTO `essennewquestdesc` VALUES (124, '<color=ffffff>大変！！シムがフェンスを食べているところを見つけたよ！<br>異常食性回復ポーションでシムの異常な食欲を戻さないと！</color><br><br><color=33ccfe>公園にいる錬金術師おばさんから<br>異常食性回復ポーションをもらおう。</color><br><br><color=ffcc00>錬金術師おばさんと会話する</color>');
INSERT INTO `essennewquestdesc` VALUES (125, '<color=ffffff>異常食性回復ポーションの一番大事な材料である黄金の豆が<br>足りないんです。 黄金の豆があればすぐ作れるのに…<br><br><color=33ccfe>ファームに豆畑を設置して黄金の豆を1個収穫したら<br>錬金術師おばさんに持っていこう</color><br><br><color=ffcc00>黄金の豆を1個収穫<br><ERASE_TAG_COMPLETE_STATE><CONDITION_GOAL_NUM=696> / <CONDITION_NUM= 696></ERASE_TAG_COMPLETE_STATE></color>');
INSERT INTO `essennewquestdesc` VALUES (126, 'NULL');
INSERT INTO `essennewquestdesc` VALUES (127, '<color=ffffff>イドゥン様に、シムの食性が変わった原因の一つかもしれない<br>この情報を伝えると、きっとシムの追跡にも役に立つと思うよ。</color><br><br><color=33ccfe>イドゥンの前哨基地にいるイドゥンに<br>シムの手がかりを報告しよう。<br><br><color=ffcc00>イドゥンと会話する</color>');
INSERT INTO `essennewquestdesc` VALUES (1000, '<color=ffffff>今回、童話の国の兵士たちの訓練コースである修練の道を<br>歩んでみるのも悪くはないと思うよ！</color><br><br><color=33ccfe>復元する童話の寺院にいるミッションチャンネルの教官と<br>会話しよう。</color><br><br><color=ffcc00>ミッションチャンネルの教官に推薦状を渡す</color><br><color=00ff00>(マイルーム→その他→ゲームカテゴリーから確認可能)</color>');
INSERT INTO `essennewquestdesc` VALUES (1001, '<color=ffffff>レースで一番大事なのは諦めずに最後まで走れる持久力なんだ。</color><br><br><color=33ccfe>復元する童話の寺院にいる対戦チャンネル教官のところに行き<br>［スピード］マップを走ろう。</color><br><br><color=ffcc00>［スピード］マップを2分30秒以内に完走</color>');
INSERT INTO `essennewquestdesc` VALUES (1002, '<color=ffffff>童話の中を走っていると、数多くの障害物に遭遇することになる。<br>そのとき、効率的に使えるジャンプを学んでみよう。</color><br><br><color=33ccfe>復元する童話の寺院にいる対戦チャンネル教官のところに行き<br>［ハードルイージー］マップを走ってみよう。</color><br><br><color=ffcc00>［ハードルイージー］マップを 2分30秒以内に完走</color>');
INSERT INTO `essennewquestdesc` VALUES (1003, '<color=ffffff>童話の中を走っていると上から下に落下する状況に<br>出くわすことがよくあるから、その練習をしておくのがいい。</color><br><br><color=33ccfe>復元する童話の寺院にいる対戦チャンネル教官のところに行き<br>［スーパージャンプ］マップを走ってみよう。</color><br><br><color=ffcc00>［スーパージャンプ］マップで着地ダッシュを2回以上成功させる</color>');
INSERT INTO `essennewquestdesc` VALUES (1004, '<color=ffffff>今まで学んできたすべての技術を忘れないための訓練だ。<br>うまくクリアするように！</color><br><br><color=33ccfe>復元する童話の寺院にいる対戦チャンネル教官のところに行き<br>［ブロックイージー］マップを走ってみよう。</color><br><br><color=ffcc00>［ブロックイージー］マップを3分以内に完走</color>');
INSERT INTO `essennewquestdesc` VALUES (1005, '<color=ffffff>修練の道は体だけではなく<br>精神力まで強く鍛える訓練だ。</color><br><br><color=33ccfe>復元する童話の寺院にいる対戦チャンネル教官のところに行き<br>［アラジン］マップを走ってみよう。</color><br><br><color=ffcc00>［アラジン］マップで怒りを1回発動</color>');
INSERT INTO `essennewquestdesc` VALUES (1006, '<color=ffffff>強い忍耐力で困難な状況を乗り越えることもできるが<br>鍛えられた体の中に内功がしっかりしていると<br>どんな状況も克服できるものだ。</color><br><br><color=33ccfe>復元する童話の寺院にいる対戦チャンネル教官のところに行き<br>［ハードルイージー］マップを走ってみよう。</color><br><br><color=ffcc00>［ハードルイージー］マップをダメージ10回以下で完走</color>');
INSERT INTO `essennewquestdesc` VALUES (1007, '<color=ffffff>これまで学んできたすべての技術を活して<br>誰よりも優秀な存在であることを証明するように。</color><br><br><color=33ccfe>復元する童話の寺院にいる対戦チャンネル教官のところに行き<br>［アラジン］マップを走ってみよう。</color><br><br><color=ffcc00>［アラジン］マップを1位で完走</color>');
INSERT INTO `essennewquestdesc` VALUES (3000, '<color=ffffff>ううう…だんだん太ってる気がする…<br>太らない食べ物ってないかしら？<br>ファームピエロ君なら知ってるかも知れない…</color><br><br><color=33ccfe>公園にいるファームピエロと話そう。</color><br><br><color=ffcc00>ファーピエロにダイエットに効く食べ物を聞く。</color>');
INSERT INTO `essennewquestdesc` VALUES (3001, '<color=ffffff>豊富な栄養素と低カロリー！<br>デカ豆ほどこの2つを満足させるものはないよ！</color><br><br><color=33ccfe>ファームに豆畑を設置して、デカ豆 1個を収穫したら<br>ミニゲーム入場ガードに持っていこう。</color><br><br><color=ffcc00>デカ豆を1個収穫して、ミニゲーム入場ガードに持っていく。</color>');
INSERT INTO `essennewquestdesc` VALUES (3002, '<color=ffffff>食事療法ダイエットですか…ふぅ…<br>聞いただけでもぞっとします…<br>でも、効果のある食べ物があるのでお教えしますわ。</color><br><br><color=33ccfe>公園にいる商店のおねえさんと話そう。</color><br><br><color=ffcc00>ミニゲーム入場ガードに食事療法ダイエットの情報を伝える</color>');
INSERT INTO `essennewquestdesc` VALUES (3003, '<color=ffffff>あの…私、品質のいいお米がないの…<br>食事療法ダイエットができるように手伝ってくれない？</color><br><br><color=33ccfe>ファームに米畑を設置して、米を5個収穫したら<br>ミニゲーム入場ガードに持っていこう。</color><br><br><color=ffcc00>米を5個収穫。<br><ERASE_TAG_COMPLETE_STATE><CONDITION_GOAL_NUM=631> / <CONDITION_NUM= 631></ERASE_TAG_COMPLETE_STATE></color>');
INSERT INTO `essennewquestdesc` VALUES (3004, '<color=ffffff>あ～頭にくる！！ 腹へって仕事ができない！！<br>ファームピエロのところに行って食事が遅れてる<br>理由を調べてくれないか！！</color><br><br><color=33ccfe>公園にいるファームピエロと話そう。</color><br><br><color=ffcc00>ファームピエロの無事を確認</color>');
INSERT INTO `essennewquestdesc` VALUES (3005, '<color=ffffff>あぁ… 昨日働きすぎてね…体の調子が悪いんだ… <br>僕の代わりに料理の材料を持ってきてくれないかい？</color><br><br><color=33ccfe>ファームにイチゴ畑を設置して、イチゴを3個収穫したら<br>ファームピエロに持っていこう。</color><br><br><color=ffcc00>イチゴを3個収穫 <ERASE_TAG_COMPLETE_STATE><CONDITION_GOAL_NUM=634> / <CONDITION_NUM= 634></ERASE_TAG_COMPLETE_STATE></color>');
INSERT INTO `essennewquestdesc` VALUES (3006, '<color=ffffff>イチゴパイが出来上がったよ！！！ あとは配達するだけだ~</color><br><br><color=33ccfe>イドゥンの前哨基地にいる、技術者ピエロと話そう。</color><br><br><color=ffcc00>技術者ピエロたちに食事を配達。</color>');
INSERT INTO `essennewquestdesc` VALUES (3007, '<color=ffffff>う…う… デカイチゴが入ってないイチゴパイなんて！！<br>イチゴパイの命はデカイチゴなんだよ！！</color><br><br><color=33ccfe>ファームにイチゴ畑を設置して、デカイチゴを 1個収穫したら<br>技術者ピエロに持っていこう。</color><br><br><color=ffcc00>デカイチゴを1個収穫<br><ERASE_TAG_COMPLETE_STATE><CONDITION_GOAL_NUM=639> / <CONDITION_NUM= 639></ERASE_TAG_COMPLETE_STATE></color>');
INSERT INTO `essennewquestdesc` VALUES (3008, '<color=ffffff>テイルズランドの住民に収穫した農作物を<br> 紹介してみることもいい経験になるだろ。</color><br><br><color=33ccfe>ファームに豆畑を設置して豆を10個収穫したら<br>ファームピエロに持って行こう。</color><br><br><color=ffcc00>豆を10個収穫<br><ERASE_TAG_COMPLETE_STATE><CONDITION_GOAL_NUM=666> / <CONDITION_NUM= 666></ERASE_TAG_COMPLETE_STATE></color>');
INSERT INTO `essennewquestdesc` VALUES (3009, '<color=ffffff>この前もらった豆の質はすごくよかったよ。<br>今度はとうもろこしを収穫してみるのはどう？</color><br><br><color=33ccfe>ファームにとうもろこし畑を設置してとうもろこしを<br>10個収穫したらファームピエロに持って行こう。</color><br><br><color=ffcc00>とうもろこしを10個収穫<br><ERASE_TAG_COMPLETE_STATE><CONDITION_GOAL_NUM=669> / <CONDITION_NUM= 669></ERASE_TAG_COMPLETE_STATE></color>');
INSERT INTO `essennewquestdesc` VALUES (3010, '<color=ffffff>デカとうもろこしをみたことあるかい？<br>それは君しか収穫できないと思う。</color><br><br><color=33ccfe>ファームにとうもろこし畑を設置してデカとうもろこしを<br>3個収穫したら、ファームピエロに持って行こう。</color><br><br><color=ffcc00>デカとうもろこしを3個収穫<br><ERASE_TAG_COMPLETE_STATE><CONDITION_GOAL_NUM=672> / <CONDITION_NUM= 672></ERASE_TAG_COMPLETE_STATE></color>');
INSERT INTO `essennewquestdesc` VALUES (3011, '<color=ffffff>デカ豆の収穫ができたら、有名人になるのも時間の問題だよ！</color><br><br><color=33ccfe>ファームに豆畑を設置してデカ豆を3個収穫したら<br>ファームピエロに持って行こう。</color><br><br><color=ffcc00>デカ豆を3個収穫<br><ERASE_TAG_COMPLETE_STATE><CONDITION_GOAL_NUM=675> / <CONDITION_NUM= 675></ERASE_TAG_COMPLETE_STATE></color>');
INSERT INTO `essennewquestdesc` VALUES (3012, '<color=ffffff>注文が殺到してるよ！！<br>まずは、VIPの錬金術師に頼まれた豆だよ。</color><br><br><color=33ccfe>ファームに豆畑を設置して豆を30個収穫したら<br>錬金術師に持って行こう。</color><br><br><color=ffcc00>豆を30個収穫<br><ERASE_TAG_COMPLETE_STATE><CONDITION_GOAL_NUM=678> / <CONDITION_NUM= 678></ERASE_TAG_COMPLETE_STATE></color>');
INSERT INTO `essennewquestdesc` VALUES (3013, '<color=ffffff>次は…あら？なすじゃん！なすはまだ収穫したことがないから<br>一度俺が品質を確認して注文を受けるかどうか判断するよ。</color><br><br><color=33ccfe>ファームになす畑を設置してなすを1個収穫したら<br>ファームピエロに持って行こう。</color><br><br><color=ffcc00>なすを1個収穫 <br><ERASE_TAG_COMPLETE_STATE><CONDITION_GOAL_NUM=681> / <CONDITION_NUM= 681></ERASE_TAG_COMPLETE_STATE></color>');
INSERT INTO `essennewquestdesc` VALUES (3014, '<color=ffffff>そろそろ本格的に注文を受けてみようか。<br>今回はイドゥン様からの注文なんだ。<br>イドゥン様は味にうるさい方だから、質のいいものを頼むよ！</color><br><br><color=33ccfe>ファームになす畑を設置してなすを7個収穫したら<br>イドゥン様に持って行こう。</color><br><color=ffcc00>なすを7個収穫<br><ERASE_TAG_COMPLETE_STATE><CONDITION_GOAL_NUM=684> / <CONDITION_NUM= 684></ERASE_TAG_COMPLETE_STATE></color>');
INSERT INTO `essennewquestdesc` VALUES (3015, '<color=ffffff>健康にはやっぱり米が一番だ！</color><br><br><color=33ccfe>ファームに米畑を設置して米を10個収穫したら<br>ファームピエロに持って行こう。</color><br><br><color=ffcc00>米を10個収穫</color>');
INSERT INTO `essennewquestdesc` VALUES (3016, '<color=ffffff>お客様をもてなすときは、何と言っても黄金の米だろう！</color><br><br><color=33ccfe>ファームに米畑を設置して黄金の米を1個収穫したら<br>ファームピエロに持って行こう。</color><br><br><color=ffcc00>黄金の米を1個収穫</color>');
INSERT INTO `essennewquestdesc` VALUES (3017, '<color=ffffff>イチゴか…僕はイチゴを見ると母さんを思い出すんだ…</color><br><br><color=33ccfe>ファームにイチゴ畑を設置してイチゴを10個収穫したら<br>ファームピエロに持って行こう。</color><br><br><color=ffcc00>イチゴを10個収穫</color>');
INSERT INTO `essennewquestdesc` VALUES (3018, '<color=ffffff>今度はちょっと難易度が高いんだ…<br>ストロベリージャムをつくりたいって～</color><br><br><color=33ccfe>ファームにイチゴ畑を設置してデカイチゴを3個収穫したら<br>ファームピエロに持って行こう。</color><br><br><color=ffcc00>デカイチゴを3個収穫</color>');
INSERT INTO `essennewquestdesc` VALUES (3019, '<color=ffffff>ジャガイモの効能が知られてから、注文が増えてきたよ～</color><br><br><color=33ccfe>ファームにジャガイモ畑を設置してジャガイモを10個収穫したら<br>ファームピエロに持って行こう。</color><br><br><color=ffcc00>ジャガイモを10個収穫</color>');
INSERT INTO `essennewquestdesc` VALUES (3020, '<color=ffffff>想像を超えたジャガイモブームだな～僕の考えが当たったんだ～</color><br><br><color=33ccfe>ファームにジャガイモ畑を設置してデカジャガイモを<br>3個収穫したら、ミニゲーム入場ガードに持って行こう。</color><br><br><color=ffcc00>デカジャガイモを3個収穫</color>');
INSERT INTO `essennewquestdesc` VALUES (3021, '<color=ffffff>図書館ピエロが本をたくさん読んだせいで<br>目が疲れたのかニンジンを注文したんだ～</color><br><br><color=33ccfe>ファームにニンジン畑を設置してニンジンを10個収穫したら<br>図書館ピエロに持って行こう。</color><br><br><color=ffcc00>ニンジンを10個収穫</color>');
INSERT INTO `essennewquestdesc` VALUES (3022, '<color=ffffff>図書館ピエロが黄金のニンジンジュースが飲みたいって！</color><br><br><color=33ccfe>ファームにニンジン畑を設置して黄金のニンジンを<br>1個収穫したら、図書館ピエロに持って行こう。</color><br><br><color=ffcc00>黄金のニンジンを1個収穫</color>');
INSERT INTO `essennewquestdesc` VALUES (3023, '<color=ffffff>最近、パン作りにはまってる人が増えた気がする！</color><br><br><color=33ccfe>ファームに小麦畑を設置して小麦を12個収穫したら<br>ファームピエロに持って行こう。</color><br><br><color=ffcc00>小麦を12個収穫</color>');
INSERT INTO `essennewquestdesc` VALUES (3024, '<color=ffffff>小麦は粉にすると、揚げ物やパンなど、色んなものに使えるよ！</color><br><br><color=33ccfe>ファームに小麦畑を設置してデカ小麦を2個収穫したら<br>ファームピエロに持って行こう。</color><br><br><color=ffcc00>デカ小麦を2個収穫</color>');
INSERT INTO `essennewquestdesc` VALUES (3025, '<color=ffffff>錬金術師おばさんがきゅうりピクルスの作り方を学んだみたい。</color><br><br><color=33ccfe>ファームにきゅうり畑を設置してきゅうりを20個収穫したら<br>ファームピエロに持って行こう。</color><br><br><color=ffcc00>きゅうりを20個収穫</color>');
INSERT INTO `essennewquestdesc` VALUES (3026, '<color=ffffff>この間のきゅうりで作ったピクルスがすごい人気だったらしい～</color><br><br><color=33ccfe>ファームにきゅうり畑を設置してデカきゅうりを3個収穫したら<br>ファームピエロに持って行こう。</color><br><br><color=ffcc00>デカきゅうりを3個収穫</color>');
INSERT INTO `essennewquestdesc` VALUES (4000, '<color=ffffff>双子姉妹が運営しているミニゲームセンターです。<br>ここではいろんなミニゲームが楽しめますよ～<br><br><color=33ccfe>ミニゲームセンターに移動したら、ミニゲーム案内に会おう。</color><br><br><color=ffcc00>ミニゲーム案内と会話する</color>');
INSERT INTO `essennewquestdesc` VALUES (4001, '<color=ffffff>［ピエロ救出作戦］は、ワニたちを避けながら川に溺れた<br>ピエロを救出するスリル満点のミニゲームです。</color><br><br><color=33ccfe>案内デスクに向かって左手中央にある［ピエロ救出作戦］を<br>プレイしよう。</color><br><br><color=ffcc00>［ピエロ救出作戦］１回プレイ<br><ERASE_TAG_COMPLETE_STATE><CONDITION_GOAL_NUM=160> / 1</ERASE_TAG_COMPLETE_STATE></color>');
INSERT INTO `essennewquestdesc` VALUES (4002, '<color=ffffff>［ペンギンを防げ］は前方から押し寄せてくるペンギンたちに<br>向かって鉄砲を発射して止めるミニゲームです。</color><br><br><color=33ccfe>［ピエロ救出作戦］に向かって左側にある<br>［ペンギンを防げ］をプレイしよう。</color><br><br><color=ffcc00>［ペンギンを防げ］を一回プレイ<br><ERASE_TAG_COMPLETE_STATE><CONDITION_GOAL_NUM=163> / 1</ERASE_TAG_COMPLETE_STATE></color>');
INSERT INTO `essennewquestdesc` VALUES (4003, '<color=ffffff>［電気パンダ］は四方から寄ってくる電気をジャンプ技術で<br>回避して点数をとるミニゲームです。</color><br><br><color=33ccfe>［ピエロ救出作戦］に向かって右側にある<br>［電気パンダ］をプレイしよう。</color><br><br><color=ffcc00>［電気パンダ］を１回プレイ<br><ERASE_TAG_COMPLETE_STATE><CONDITION_GOAL_NUM=166> / 1</ERASE_TAG_COMPLETE_STATE></color>');
INSERT INTO `essennewquestdesc` VALUES (6000, '<color=ffffff>錬金術師のおじさんが童話の国一の美女だったおばさんと<br>どうやって結婚できたか知りたい！！</color><br><br><color=33ccfe>公園にある村役場のピエロと話してみよう。</color><br><br><color=ffcc00>村役場のピエロに錬金術師について聞いてみる</color>');
INSERT INTO `essennewquestdesc` VALUES (6001, '<color=ffffff>クククッ、知りたいことがあると？</color><br><br><color=33ccfe>復元する童話の寺院にいる対戦チャンネル教官のところに行き<br>［カエルの王子］を走ってみよう。</color><br><br><color=ffcc00>［No.7 池に落ちた金の鞠］カードを１枚収集<br><ERASE_TAG_COMPLETE_STATE><CONDITION_GOAL_NUM=347> / <CONDITION_NUM= 347></ERASE_TAG_COMPLETE_STATE></color>');
INSERT INTO `essennewquestdesc` VALUES (6002, '<color=ffffff>ラブラブ木の葉をどこに置いたっけ？<br>もうちょっと待っててくれる？すぐ探してやるから。</color><br><br><color=33ccfe>公園にいるファームピエロと会話しよう。</color><br><br><color=ffcc00>ファームピエロからラブラブ木の葉をもらう</color>');
INSERT INTO `essennewquestdesc` VALUES (6003, '<color=ffffff>キューピットの水薬なら、俺が作ってやるよ！！<br>代わりに今日は俺が料理の当番なんで材料を…</color><br><br><color=33ccfe>ファームにとうもろこし畑を設置してとうもろこしを<br>3本収穫したら錬金術師に持って行こう。</color><br><br><color=ffcc00>とうもろこしを3本収穫<br><ERASE_TAG_COMPLETE_STATE><CONDITION_GOAL_NUM=231> / <CONDITION_NUM= 231></ERASE_TAG_COMPLETE_STATE></color>');
INSERT INTO `essennewquestdesc` VALUES (6004, '<color=ffffff>これがお母さんが言ったキューピットの水薬なんだな…。<br>でも、間違って作られたかも知れないから<br>錬金術師のおばちゃんにみせてみたら？</color><br><br><color=33ccfe>公園にいる錬金術師のおばさんと話してみよう。</color><br><br><color=ffcc00>錬金術師のおばさんにキューピットの水薬を見せる。</color>');
INSERT INTO `essennewquestdesc` VALUES (6005, '<color=ffffff>待ってる間、ちょっとしたことをやってくれないか？<br>今日はワイフに小さなプレゼントをしようと思うんだ…</color><br><br><color=33ccfe>復元する童話の寺院にいる対戦チャンネル教官のところ行き<br>［ジャックと豆の木］マップを走ろう。</color><br><br><color=ffcc00>［No.1 牛と交換した魔法の豆］カードを3枚収集<br><ERASE_TAG_COMPLETE_STATE><CONDITION_GOAL_NUM=226> / <CONDITION_NUM= 226></ERASE_TAG_COMPLETE_STATE></color>');
INSERT INTO `essennewquestdesc` VALUES (6006, '<color=ffffff>キューピットの水薬を成長水に変えてくれましたね。<br>今日は好きな人のファームに行ってコッソリ成長水を<br>撒いてあげるのはどうでしょう？</color><br><br><color=33ccfe>公園の中にあるミニゲーム入場ガードと会話しよう。</color><br><br><color=ffcc00>ミニゲーム入場ガードに錬金術師の恋の方式について話す</color>');
INSERT INTO `essennewquestdesc` VALUES (6007, '<color=ffffff>今回、俺の憧れの武器であるなぎなたに変えようと思うんだが…<br>武器を依頼しに行く時間がないんだ…</color><br><br><color=33ccfe>公園にいる錬金術師おじさんと話そう。</color><br><br><color=ffcc00>錬金術師おじさんになぎなたの材料を持っていく。</color>');
INSERT INTO `essennewquestdesc` VALUES (6008, '<color=ffffff>なぎなたを作るには材料が少々足りないな…</color><br><br><color=33ccfe>イドゥンの前哨基地の技術者ピエロと話そう。</color><br><br><color=ffcc00>技術者ピエロに鉄を5つお願いする。<br><ERASE_TAG_COMPLETE_STATE><CONDITION_GOAL_NUM=593> / <CONDITION_NUM= 593></ERASE_TAG_COMPLETE_STATE></color>');
INSERT INTO `essennewquestdesc` VALUES (6009, '<color=ffffff>鉄はただでやれるけど… 今度製作する器具に豆の木の枝が<br>必要なんだ… 手伝ってくれたら、俺も力を貸してやるよ！！</color><br><br><color=33ccfe>復元する童話の寺院にいる対戦チャンネル教官のところに行き<br>［ジャックと豆の木］マップを走ろう。</color><br><br><color=ffcc00>［ジャックと豆の木］マップから出る豆の木の枝を5つ集める。<br><ERASE_TAG_COMPLETE_STATE><CONDITION_GOAL_NUM=596> / <CONDITION_NUM= 596></ERASE_TAG_COMPLETE_STATE></color>');
INSERT INTO `essennewquestdesc` VALUES (6010, '<color=ffffff>うっ… 俺が失敗するなんて…作り直せる時間を稼がなきゃな… <br>この証明書なら… 絶対Hellチャンネル教官の心を動かせるだろう。</color><br><br><color=33ccfe>復元する童話の寺院にいるHellチャンネル教官と話そう。</color><br><br><color=ffcc00>Hellチャンネル教官に兵士任官証明書を渡す。</color>');
INSERT INTO `essennewquestdesc` VALUES (6011, '<color=ffffff>シャンゼリゼ女王様は、色んな面でテイルズランドを助けて<br>下さっていますので、お礼の贈り物をしたいのですが<br>何がいいのか分からなくて！</color><br><br><color=33ccfe>シャンゼリゼ女王様への贈り物を集めよう。</color><br><br><color=ffcc00>テイルズランドの住民たちが準備したプレゼントを集める。</color>');
INSERT INTO `essennewquestdesc` VALUES (6012, '<color=ffffff>テイルズランドで一番個性的なアイテムと言えば<br>やっぱり！！錬金アイテムだろ～<br>今回、女王様のために特別に製作した錬金ドレス！！</color><br><br><color=33ccfe>［トレーニング］マップで出てくる［アンリ3世の決断］カードを<br>3枚集めたら錬金術師に持って行こう。</color><br><br><color=ffcc00>［No.27 アンリ3世の決断］カードを3枚収集<br><ERASE_TAG_COMPLETE_STATE><CONDITION_GOAL_NUM=602> / <CONDITION_NUM= 602></ERASE_TAG_COMPLETE_STATE></color>');
INSERT INTO `essennewquestdesc` VALUES (6013, '<color=ffffff>女王様への贈り物は、あらゆる悩みをすべて無くしてくれる<br>ハクナマタタのお守りがぴったりだけど…無くしてしまったの…</color><br><br><color=33ccfe>［桃太郎］マップで、アキが失くした<br>ハクナマタタのお守りを探そう。</color><br><br><color=ffcc00>ハクナマタタのお守りを1つ収集<br><ERASE_TAG_COMPLETE_STATE><CONDITION_GOAL_NUM=605> / <CONDITION_NUM= 605></ERASE_TAG_COMPLETE_STATE></color>');
INSERT INTO `essennewquestdesc` VALUES (6014, '<color=ffffff>女王様のお国の人たちもミニゲームをする事ができたら<br>みんな喜ぶと思うわ！！</color><br><br><color=33ccfe>イドゥンの前哨基地にいるピエロと話そう。</color><br><br><color=ffcc00>技術者ピエロに［ピエロ救出作戦］の設計図をお願いする。</color>');
INSERT INTO `essennewquestdesc` VALUES (6015, '<color=ffffff>設計図は完成したが…何か足りない気がするんだな…</color><br><br><color=33ccfe>ミニゲームセンターで［ピエロ救出作戦］を1回プレイしよう。</color><br><br><color=ffcc00>［ピエロ救出作戦］を1回プレイする。</color>');
INSERT INTO `essennewquestdesc` VALUES (6016, '<color=ffffff>女王様のために特別な種子を作ってみないかい？<br>女王様もお気に召すはずだよ。</color><br><br><color=33ccfe>ファームに豆畑を設置して、豆を10個収穫したら<br>ファームピエロに持っていこう。</color><br><br><color=ffcc00>豆を10個収穫。<br><ERASE_TAG_COMPLETE_STATE><CONDITION_GOAL_NUM=612> / <CONDITION_NUM= 612></ERASE_TAG_COMPLETE_STATE></color>');
INSERT INTO `essennewquestdesc` VALUES (6017, '<color=ffffff>いいね！！ 今度は、少量で満腹感を感じられる米を集めよう！！</color><br><br><color=33ccfe>ファームにお米畑を設置して、米を10個収穫したら<br>ファームピエロに持っていこう。</color><br><br><color=ffcc00>米を10個収穫<br><ERASE_TAG_COMPLETE_STATE><CONDITION_GOAL_NUM=615> / <CONDITION_NUM= 615></ERASE_TAG_COMPLETE_STATE></color>');
INSERT INTO `essennewquestdesc` VALUES (6018, '<color=ffffff>よし！！ 今度は、肌老化を防ぐ要素がたくさん含まれている<br>とうもろこしを収穫しよう！！</color><br><br><color=33ccfe>ファームにとうもろこし畑を設置して<br>とうもろこしを10個収穫したら、ファームピエロに持っていこう。</color><br><br><color=ffcc00>とうもろこしを10個収穫。<br><ERASE_TAG_COMPLETE_STATE><CONDITION_GOAL_NUM=618> / <CONDITION_NUM= 618></ERASE_TAG_COMPLETE_STATE></color>');
INSERT INTO `essennewquestdesc` VALUES (6019, '<color=ffffff>あぁ…KARAがテイルズランドに来るためにワープをしたんだけど<br>失敗してしまって童話の中に閉じ込められちゃったんだ！</color><br><br><color=33ccfe>公園にいる錬金術師と話そう。</color><br><br><color=ffcc00>錬金術師と会話する</color>');
INSERT INTO `essennewquestdesc` VALUES (6020, 'NULL');
INSERT INTO `essennewquestdesc` VALUES (6021, 'NULL');
INSERT INTO `essennewquestdesc` VALUES (6022, '<color=ffffff>鬼たちに商品のスカートを盗まれた！？<br>ITEM商店の方のためにスカートを取り戻さないと！</color><br><br><color=33ccfe>［桃太郎］マップを完走してスカートを取り戻したら<br>ITEM商店のお姉さんに持って行こう。</color><br><br><color=ffcc00>盗まれたスカートを1個収集</color>');
INSERT INTO `essennewquestdesc` VALUES (6023, 'NULL');
INSERT INTO `essennewquestdesc` VALUES (6024, '<color=ffffff>また鬼たちに盗まれたんですか！？<br>このまま鬼たちをほっといてはいけません。<color><br><br><color=33ccfe>［桃太郎］マップを完走して、はさみと服地を取り戻したら<br>ITEM商店のお姉さんに持って行こう。</color><br><br><color=ffcc00>盗まれたはさみ1個と服地を1個収集</color>');
INSERT INTO `essennewquestdesc` VALUES (6025, 'NULL');
INSERT INTO `essennewquestdesc` VALUES (6026, '<color=ffffff>困難の前でお互いの力を合わせることは素晴らしいことです！<br>ピエロ特製のこのピコピコハンマーをアキさんに渡してください。</color><br><br><color=33ccfe>イドゥンからもらったピコピコハンマーをアキに渡そう。</color><br><br><color=ffcc00>占星術師アキにピコピコハンマーを渡す</color>');
INSERT INTO `essennewquestdesc` VALUES (6027, '<color=ffffff>他のところにも鬼たちが現れるかもしれないので、<br>もう一度鬼たちを注意してきてください！<color><br><br><color=33ccfe>［桃太郎］マップのゴール地点にいる子分鬼を踏み倒そう。 </color><br><br><color=ffcc00>［桃太郎］マップのゴール地点にいる子分鬼を一匹踏み倒す </color>');
INSERT INTO `essennewquestdesc` VALUES (6028, '<color=ffffff>おかげさまで、鬼の心配はなくなりました！<br>それより、対戦チャンネルの教官様が<br>お探しでしたよ。<color><br><br><color=33ccfe>対戦チャンネルの教官を訪ねよう。</color><br><br><color=ffcc00>対戦チャンネルの教官と会話をする</color>');
INSERT INTO `essennewquestdesc` VALUES (6029, 'NULL');
INSERT INTO `essennewquestdesc` VALUES (6030, '<color=ffffff>アラビアの星座の本の内容が知りたいと？なら、［アラジン］マップだ！<br>あそこにはアラビアの神秘な力が潜められた水晶玉がある！<color><br><br><color=33ccfe>［アラジン］マップを走って神秘なアラビアの水晶玉を<br>手に入れたら、アキに持って行こう。</color><br><br><color=ffcc00>神秘なアラビアの水晶玉を1個収集</color>');
INSERT INTO `essennewquestdesc` VALUES (6031, '<color=ffffff>望遠鏡をくれた錬金術師おばさんに何かお返しがしたいわ！<br>重金属の解毒にいい紅茶はどうかしら～</color><br><br><color=33ccfe>ファームに桃畑を設置して桃を10個収穫したら<br>占星術師アキに持って行こう。</color><br><br><color=ffcc00>桃を10個収穫</color><br><color=00ff00>(桃はMyルーム->その他->ファームカテゴリーで確認可能)</color>');
INSERT INTO `essennewquestdesc` VALUES (6032, 'NULL');
INSERT INTO `essennewquestdesc` VALUES (6033, '<color=ffffff>あっ！！どうしよう…またデカイチゴ入れるの忘れた…<br>イチゴパイにデカイチゴが入ってないのが分かったら、みんながっかりするよな…</color><br><br><color=33ccfe>ファームにイチゴ畑を設置してデカイチゴを5個収穫したら<br>ファームピエロに持って行こう。</color><br><br><color=ffcc00>デカイチゴを5個収穫</color><br><color=00ff00>（デカイチゴはMyルームー＞その他ー＞ファームカテゴリーで確認可能）</color>');
INSERT INTO `essennewquestdesc` VALUES (6034, '<color=ffffff>イチゴパイ完成！！今度は完璧だよ～～<br>このイチゴパイをアキに持ってってくれ～</color><br><br><color=33ccfe>イチゴパイを占星術師アキに渡そう。</color><br><br><color=ffcc00>占星術師アキにイチゴパイを配達</color>');
INSERT INTO `essennewquestdesc` VALUES (6035, 'NULL');
INSERT INTO `essennewquestdesc` VALUES (6036, '<color=ffffff>ファームピエロ…よくこの本を借りるな…<br>意外に感受性豊かなヤツかも～</color><br><br><color=33ccfe>［かぐや姫］の本をファームピエロに持って行こう。</color><br><br><color=ffcc00>［かぐや姫］の本をファームピエロに渡す</color>');
INSERT INTO `essennewquestdesc` VALUES (6037, '<color=ffffff>ラブメッセンジャーの私がこんなミスをするとは！<br>預かったラブレターを失くしてしまいました！！</color><br><br><color=33ccfe>［4 in Oneder land ］からラブレターを捜して<br>ミニゲーム案内のお姉さんに渡そう。</color><br><br><color=ffcc00>なくしたラブレターを1個収集</color>');
INSERT INTO `essennewquestdesc` VALUES (6038, '<color=ffffff>たぶん…今ミニゲームセンターのピエロたちは仕事中だと思うよ～<br>だから、代わりにミニゲーム案内にイチゴオレを渡してくれ！</color><br><br><color=33ccfe>ミニゲーム案内のお姉さんにイチゴオレを渡そう。</color><br><br><color=ffcc00>ミニゲーム案内のお姉さんにイチゴオレを配達</color>');
INSERT INTO `essennewquestdesc` VALUES (7000, '<color=ffffff>アリスの羊皮紙ボックスに入っているクエストをクリアして<br>アキのところに行くと、クリアしたクエスト毎に<br>「アリスの証」がもらえるよ～</color><br><br><color=33ccfe>「アリスの証」を3個集めて図書館ピエロに持って行こう。</color><br><br><color=ffcc00>「アリスの証」を3個収集<br><ERASE_TAG_COMPLETE_STATE><CONDITION_GOAL_NUM=895> / <CONDITION_NUM= 895></ERASE_TAG_COMPLETE_STATE></color>');
INSERT INTO `essennewquestdesc` VALUES (8000, '<color=ffffff>ワープ召喚装置を稼動させるためには触媒剤である<br>「KARAの結晶体」が必要だそうです。</color><br><br><color=33ccfe>錬金術師おばさんにKARAの結晶体を作ってもらおう。</color><br><br><color=ffcc00>KARAの結晶体を1個収集<br><ERASE_TAG_COMPLETE_STATE><CONDITION_GOAL_NUM=773> / <CONDITION_NUM= 773></ERASE_TAG_COMPLETE_STATE></color>');
INSERT INTO `essennewquestdesc` VALUES (8001, '<color=ffffff>ワープ召喚装置を稼動させるためには触媒剤である<br>「KARAの結晶体」が必要だそうです。</color><br><br><color=33ccfe>錬金術師おばさんにKARAの結晶体を作ってもらおう。</color><br><br><color=ffcc00>KARAの結晶体を1個収集<br><ERASE_TAG_COMPLETE_STATE><CONDITION_GOAL_NUM=813> / <CONDITION_NUM= 813></ERASE_TAG_COMPLETE_STATE></color>');
