INSERT INTO `essennewquestdesc` VALUES (9003, '<color=ffffff>[レベル]</color><br><color=ffcc00>★</color><br><br><color=ffffff>[要求事項]</color><br><color=ffcc00>［No.21 桃から生まれた桃太郎］カードを3枚収集<br><ERASE_TAG_COMPLETE_STATE><CONDITION_GOAL_NUM=358> / <CONDITION_NUM= 358></ERASE_TAG_COMPLETE_STATE></color>');
