INSERT INTO `tblavataritemdesc` VALUES (2214, 1001, 1, 0, 8000, 1, 1, 0, 0, 0, 0, '[No.01] 紙切れクエスト', 5009, 0, 0, 1, 0, 1, 0, 0, 0, 0, 0, '<color=00ff00>担当者</color> : ファームピエロ<br><color=00ff00>レベル</color> : ★<br><br> <color=ffcc00>[要求事項]</color><br>デカ豆を1個収穫<br><br><color=33ccfe>[報償]</color><br>400 EXP<br>18 TL', 0, 0, 0, 1, NULL);
