DROP PROCEDURE IF EXISTS `usp_capsuleMachineDeleteItem`;
delimiter ;;
CREATE PROCEDURE `usp_capsuleMachineDeleteItem`(IN `machineNum` INT, IN `itemNum` INT)
  NO SQL 
BEGIN
	DECLARE existCapsuleMachine, existItem, insertedItem INT;  
	DECLARE ret INT;
	SET existCapsuleMachine = (SELECT COUNT(*) FROM tblAvatarItemDesc WHERE fdItemNum = machineNum);        
	SET existItem = (SELECT COUNT(*) FROM tblAvatarItemDesc WHERE fdItemNum = ItemNum);        
	SET insertedItem = (SELECT COUNT(*) FROM SettingCapsuleMachineItemList WHERE fdItemNum = itemNum AND fdMachineNum = machineNum);
	SET ret = 0;
	this_proc:BEGIN
		START TRANSACTION;
			IF insertedItem > 0  AND existCapsuleMachine > 0 AND existItem > 0 THEN        
				DELETE FROM SettingCapsuleMachineItemList WHERE fdMachineNum = machineNum AND fdItemNum = itemNum;  
				IF ROW_COUNT() = 0 THEN
										SET ret = 1;
					ROLLBACK;
				END IF;
				
				DELETE FROM GameDataCapsuleMachineItemCount WHERE fdMachineNum = machineNum AND fdItemNum = itemNum;
				IF ROW_COUNT() = 0 THEN
										SET ret = 1;
					ROLLBACK;
				END IF;
			ELSE
				SET ret = 1;
				ROLLBACK;
			END IF;
		COMMIT;
	END;
	SELECT ret;
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for usp_capsuleMachineEditItem
-- ----------------------------
DROP PROCEDURE IF EXISTS `usp_capsuleMachineEditItem`;
delimiter ;;
CREATE PROCEDURE `usp_capsuleMachineEditItem`(IN `machineNum` INT, IN `itemNum` INT, IN `itemAmount` INT, IN `itemMax` INT)
  NO SQL 
BEGIN
	DECLARE existCapsuleMachine, existItem, insertedItem INT;  
	DECLARE ret INT;
	SET existCapsuleMachine = (SELECT COUNT(*) FROM tblAvatarItemDesc WHERE fdItemNum = machineNum);        
	SET existItem = (SELECT COUNT(*) FROM tblAvatarItemDesc WHERE fdItemNum = ItemNum);        
	SET insertedItem = (SELECT COUNT(*) FROM SettingCapsuleMachineItemList WHERE fdItemNum = itemNum AND fdMachineNum = machineNum);
	SET ret = 0;
	this_proc:BEGIN
		START TRANSACTION;
			IF insertedItem > 0  AND existCapsuleMachine > 0 AND existItem > 0 THEN        
				UPDATE SettingCapsuleMachineItemList SET fdItemMax = itemMax WHERE fdMachineNum = machineNum AND fdItemNum = itemNum;
				IF ROW_COUNT() = 0 THEN
										SET ret = 1;
					ROLLBACK;
				END IF;
				
				UPDATE GameDataCapsuleMachineItemCount SET fdItemCount = itemAmount WHERE fdMachineNum = machineNum AND fdItemNum = itemNum;
				IF ROW_COUNT() = 0 THEN
										SET ret = 1;
					ROLLBACK;
				END IF;
			ELSE
				SET ret = 1;
				ROLLBACK;
			END IF;
		COMMIT;
	END;
	SELECT ret;
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for usp_capsuleMachineGetMachineInfoForTool
-- ----------------------------
DROP PROCEDURE IF EXISTS `usp_capsuleMachineGetMachineInfoForTool`;
delimiter ;;
CREATE PROCEDURE `usp_capsuleMachineGetMachineInfoForTool`(IN `machineNum` INT)
  NO SQL 
BEGIN
	DECLARE RotateGroupNum INT DEFAULT 0;
	DECLARE RotateMachineNum INT DEFAULT 0;
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
	this_proc:BEGIN
		START TRANSACTION;
			IF machineNum <> 0 THEN
			
				SELECT t1.fdMachineNum, t1.fdLevel, t1.fdItemNum, t2.fdItemCount, t1.fdItemMax
				FROM SettingCapsuleMachineItemList t1 JOIN GameDataCapsuleMachineItemCount t2              
				ON t1.fdMachineNum = t2.fdMachineNum AND t1.fdItemNum = t2.fdItemNum
				JOIN EssenCapsuleMachineUsingList as t5 on t1.fdMachineNum = t5.fdMachineNum
				WHERE t1.fdMachineNum = machineNum;    
				
			END IF;
		
		COMMIT;
	END;
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for usp_capsuleMachineInsertItem
-- ----------------------------
DROP PROCEDURE IF EXISTS `usp_capsuleMachineInsertItem`;
delimiter ;;
CREATE PROCEDURE `usp_capsuleMachineInsertItem`(IN `machineNum` INT, IN `level` INT, IN `itemNum` INT, IN `itemMax` INT)
  NO SQL 
BEGIN
	DECLARE existCapsuleMachine, existItem, insertedItem INT;  
	DECLARE ret INT;
	SET existCapsuleMachine = (SELECT COUNT(*) FROM tblAvatarItemDesc WHERE fdItemNum = machineNum);        
	SET existItem = (SELECT COUNT(*) FROM tblAvatarItemDesc WHERE fdItemNum = ItemNum);        
	SET insertedItem = (SELECT COUNT(*) FROM SettingCapsuleMachineItemList WHERE fdItemNum = itemNum AND fdMachineNum = machineNum);
	SET ret = 0;
	this_proc:BEGIN
		IF insertedItem > 0 THEN
						SET ret = 1;
			LEAVE this_proc;
		END IF;
			
		IF level < 1 OR level > 5 THEN
			SET ret = 2;
			LEAVE this_proc;
		END IF;

		IF existCapsuleMachine < 1 OR existItem < 1 THEN
						SET ret = 3;
			LEAVE this_proc;
		ELSE 
			START TRANSACTION;
				VALUES (machineNum, level, itemNum, itemMax);
			
				VALUES (machineNum, itemNum, itemMax, NOW());
			COMMIT;
		END IF;
	END;
	SELECT ret;
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for usp_capsuleMachineReset
-- ----------------------------
DROP PROCEDURE IF EXISTS `usp_capsuleMachineReset`;
delimiter ;;
CREATE PROCEDURE `usp_capsuleMachineReset`(IN `machineNum` INT, IN `returnRate` INT)
  NO SQL 
BEGIN
	DECLARE retval INT;
	SET retval = 0;
	SET SESSION TRANSACTION ISOLATION LEVEL SERIALIZABLE;
	this_proc:BEGIN
		DECLARE LimitItemCountRate INT;
		DECLARE machineKind INT;
		DECLARE RotateGroupNum INT DEFAULT 0;
		DECLARE settingMachineNum INT;
		DECLARE presult INT DEFAULT 0;
		DECLARE MaxRateNumber INT;
		
		SET LimitItemCountRate = 50;
		START TRANSACTION;
			
			IF machineNum <> 0 THEN
			
				IF EXISTS (SELECT * FROM GameDataCapsuleMachineItemCount WHERE fdMachineNum = machineNum AND DATE_ADD(NOW(), INTERVAL -10 SECOND) < fdLastResetTime) THEN
					ROLLBACK;
				END IF;
				
				SELECT fdRotateGroupNum INTO RotateGroupNum FROM EssenRotateCapsuleMachineGroup WHERE fdMachineNum = machineNum;
				IF RotateGroupNum <> 0 THEN
					CREATE TEMPORARY TABLE RotateMachineRate
					(
						fdNum INT PRIMARY KEY AUTO_INCREMENT,
						fdMachineNum INT, fdRateNumber INT, fdSumRateNumber INT
					) ENGINE = MEMORY;
								
					WHERE fdRotateGroupNum = RotateGroupNum AND fdMachineNum <> machineNum ORDER BY fdGroupRate ASC;
					
					CREATE TEMPORARY TABLE tempTable2 ENGINE = MEMORY SELECT * FROM RotateMachineRate;				
					IF ROW_COUNT() <> 0 THEN
						UPDATE RotateMachineRate t1 SET t1.fdSumRateNumber = (SELECT SUM(t2.fdRateNumber) FROM tempTable2 t2 WHERE t2.fdNum <= t1.fdNum);
						SET MaxRateNumber = (SELECT MAX(fdSumRateNumber) FROM RotateMachineRate);
						SET presult = FLOOR(RAND() * MaxRateNumber + 1);
						IF presult > MaxRateNumber OR presult < 1 THEN
								SET presult = MaxRateNumber;
						END IF;

						SELECT fdMachineNum INTO settingMachineNum FROM RotateMachineRate WHERE fdSumRateNumber >= presult ORDER BY fdSumRateNumber ASC LIMIT 1;

					ELSE
						SET settingMachineNum = machineNum;
					END IF;

					DELETE t1 FROM GameDataCapsuleMachineItemCount t1 JOIN EssenRotateCapsuleMachineGroup t2 ON t1.fdMachineNum = machineNum AND t2.fdRotateGroupNum = RotateGroupNum;
				
					UPDATE GameDataRotateSettingCapsuleMachine SET fdMachineNum = settingMachineNum WHERE fdRotateGroupNum = RotateGroupNum;

					IF ROW_COUNT() = 0 THEN
						INSERT GameDataRotateSettingCapsuleMachine VALUES (RotateGroupNum, settingMachineNum);
					END IF;
					drop temporary table RotateMachineRate;
					drop temporary table tempTable2;
				END IF;
				
				
				UPDATE GameDataCapsuleMachineItemCount t1, SettingCapsuleMachineItemList t2
				SET fdItemCount = t2.fdItemMax, fdLastResetTime = NOW()
				WHERE t1.fdMachineNum = t2.fdMachineNum AND t1.fdItemNum = t2.fdItemNum
				AND t1.fdMachineNum = machineNum;
				
				IF ROW_COUNT() = 0 THEN 
					IF RotateGroupNum = 0 THEN
								FROM SettingCapsuleMachineItemList WHERE fdMachineNum = machineNum);
					ELSE
								FROM SettingCapsuleMachineItemList t1 JOIN GameDataRotateSettingCapsuleMachine t2 ON t1.fdMachineNum = machineNum
									WHERE t2.fdRotateGroupNum = RotateGroupNum);
					END IF;
					IF ROW_COUNT() = 0 THEN 
						ROLLBACK;
					END IF;
				END IF;
				
				UPDATE GameDataCapsuleMachineResetCount SET fdResetCount = fdResetCount + 1 WHERE fdMachineNum = machineNum;
				IF ROW_COUNT() = 0 THEN
				END IF;			
								
			ELSE
				IF EXISTS (SELECT * FROM GameDataCapsuleMachineItemCount WHERE DATE_ADD(NOW(), INTERVAL -10 SECOND) < fdLastResetTime) THEN
					ROLLBACK;
				END IF;
				
				UPDATE GameDataCapsuleMachineItemCount t1, SettingCapsuleMachineItemList t2
				SET fdItemCount = t2.fdItemMax, fdLastResetTime = NOW()
				WHERE t1.fdMachineNum = t2.fdMachineNum AND t1.fdItemNum = t2.fdItemNum;
				
				IF ROW_COUNT() = 0 THEN 
							WHERE t1.fdMachineNum NOT IN (SELECT t2.fdMachineNum FROM EssenRotateCapsuleMachineGroup t2));
					
					DELETE t1 FROM GameDataRotateSettingCapsuleMachine t1
					WHERE t1.fdRotateGroupNum NOT IN (SELECT DISTINCT t2.fdRotateGroupNum FROM EssenRotateCapsuleMachineGroup t2);
					
					SET @row = 0;
					SELECT t2.fdRotateGroupNum, t2.fdMachineNum FROM (SELECT t1.fdMachineNum, t1.fdRotateGroupNum, (@row := @row + 1) AS fdRowNumber 
					FROM EssenRotateCapsuleMachineGroup t1 ORDER BY fdMachineNum) AS t2 WHERE t2.fdRowNumber = '1' AND t2.fdRotateGroupNum NOT IN(SELECT t3.fdRotateGroupNum FROM GameDataRotateSettingCapsuleMachine t3);
					
					
					
				END IF;
				
				UPDATE GameDataCapsuleMachineResetCount SET fdResetCount = fdResetCount + 1 WHERE fdMachineNum IN (SELECT DISTINCT fdMachineNum FROM SettingCapsuleMachineItemList);
				IF ROW_COUNT() = 0 THEN
				END IF;
				
			END IF;
			
		COMMIT;
	END;
	END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for usp_GM_giveUserPoint
-- ----------------------------
DROP PROCEDURE IF EXISTS `usp_GM_giveUserPoint`;
delimiter ;;
CREATE PROCEDURE `usp_GM_giveUserPoint`(IN `nickname` VARCHAR(50), IN `rewardGroup` INT, IN `point` INT)
  NO SQL 
BEGIN
	DECLARE userNum int;
	DECLARE point_accumulate int;
	DECLARE point_current int;
	DECLARE ret int DEFAULT 0;
	
	proc:BEGIN
		select fdUserNum into userNum from UserInfo where fdnickname = nickname;

		if userNum is null then
			set ret = 1;
			LEAVE proc;
		END IF;
	
		SELECT fdPoint, fdPointAccumulated INTO point_current, point_accumulate
		FROM UserInfoPoint WHERE fdUserNum = userNum AND fdRewardCondition = rewardGroup;
		
		IF point_current IS NULL THEN
			SET point_accumulate = 0;
			SET point_current = 0;
		END IF;
			
		IF point > 0 THEN
			SET point_accumulate = point_accumulate + point;
		END IF;
			
		IF point_current + point < 0 THEN
			SET ret = 1;
			LEAVE proc;
		END IF;
			
		SET point_current = point_current + point;
		
		UPDATE UserInfoPoint SET fdPoint = point_current, fdPointAccumulated = point_accumulate WHERE fdUserNum = userNum AND fdRewardCondition = rewardGroup;
		
	END;
	SELECT ret;
END
;;
delimiter ;

SET FOREIGN_KEY_CHECKS = 1;
